saved.lines??={};
const lineBeforeControls=lineData;lineData=function(i){return {...lineBeforeControls(i),status:saved.lines[factoryIndex()+'-'+i]||lineSpecs[i].status}};
window.demoLineStatus=i=>lineData(i).status;
for(const b of saved.newBatches||[])if(/^BT-D\d+$/.test(b.id)&&Number.isInteger(b.factory)&&b.factory>=0&&b.factory<4&&Number.isInteger(b.line)&&b.line>=0&&b.line<3&&!allBatches.some(x=>x.id===b.id))allBatches.push({...b,product:lineSpecs[b.line].product,stage:0,status:'Queued',progress:0,units:10000});
function newDemoBatch(){if(state.factory<0){openModal('Select a factory for a new batch',factories.map((f,i)=>`<button class="factory-pick" onclick="state.factory=${i};render();newDemoBatch()">${f.name} →</button>`).join(''));return}if(allBatches.length>=100){openModal('Demo batch limit reached','This local demonstration supports up to 100 batch records.');return}const b={id:'BT-D'+Date.now(),factory:state.factory,line:state.line,product:lineSpecs[state.line].product,stage:0,status:'Queued',progress:0,units:10000};allBatches.push(b);saved.newBatches??=[];saved.newBatches.push({id:b.id,factory:b.factory,line:b.line});eventLog(b.id+' queued for demo execution','Process');render();batchDetail(b.id)}
const batchActionBeforeControls=batchAction;batchAction=function(id,action){const b=findBatch(id);if(!b)return;if(b.status==='Queued'){if(action!=='start')return;saved.batches[id]={stage:0,status:'Running',progress:5};eventLog(id+' started in demonstration','Process',b.factory);render();batchDetail(id);return}batchActionBeforeControls(id,action)};
const detailBeforeControls=batchDetail;batchDetail=function(id){detailBeforeControls(id);const b=findBatch(id);if(b?.status==='Queued'){const actions=$('#modalbody .actions');if(actions)actions.innerHTML=opButton('Start demo batch',`batchAction('${id}','start')`)+opButton('Batch procedure',"documentCenter('Process')")}};
const processBeforeControls=processView;processView=function(){return processBeforeControls().replace(opButton('All stages','op.stage=-1;render()'),`<div class="actions" style="margin:0">${opButton('New demo batch','newDemoBatch()')}${opButton('All stages','op.stage=-1;render()')}</div>`)};
function lineControls(){if(state.factory<0){openModal('Choose a factory for line controls',factories.map((f,i)=>`<button class="factory-pick" onclick="state.factory=${i};render();lineControls()">${f.name} →</button>`).join(''));return}const l=lineData(state.line);openModal('Line '+(state.line+1)+' · Demonstration controls',`<p>${scopeName()} · ${l.name}</p><div class="metric-reading">${l.status}</div><p>These buttons change browser-local demo state only. They do not command equipment or bypass production procedures.</p><div class="actions">${opButton('Run demo line',"setDemoLine('Running')")}${opButton('Stop demo line',"setDemoLine('Stopped')")}${opButton('Set changeover',"setDemoLine('Changeover')")}</div>`)}
function setDemoLine(status){if(state.factory<0||!['Running','Stopped','Changeover'].includes(status))return;saved.lines[factoryIndex()+'-'+state.line]=status;eventLog('Packaging line '+(state.line+1)+' '+status+' in demo','Packaging');render();lineControls()}
const packBeforeControls=packagingView;packagingView=function(){return packBeforeControls().replace(opButton('Recovery plan →','openAction(0)'),opButton('Demo controls','lineControls()')+opButton('Recovery plan →','openAction(0)')).replace('Changeover in progress',lineData(state.line).status==='Stopped'?'Stopped in demo':'Changeover in progress')};
